package com.bank.video;

import java.util.*;
import java.util.logging.*;

public class StreamingDemo {
    private static final Logger log = Logger.getLogger("Video");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TranscodePipeline pipeline = new TranscodePipeline();
        String videoId = "VID-ADVISORY-01";

        // Upload → async transcoding into a bitrate ladder
        pipeline.upload(videoId, "/raw/advisory.mov");
        pipeline.runWorkers();  // process queued jobs
        List<Variant> ladder = pipeline.ladderOf(videoId);
        log.info(() -> "Ladder: " + ladder);

        // Rajesh streams with fluctuating bandwidth (bytes/sec)
        AdaptiveStreamer streamer = new AdaptiveStreamer();
        long[] bandwidths = { 5_000_000, 2_000_000, 600_000, 2_500_000 };
        for (long bw : bandwidths) {
            Variant v = streamer.selectVariant(ladder, bw);
            log.info(() -> "bandwidth " + bw + " -> stream " + v.resolution());
        }

        // Millions of views: sharded counting
        ViewCounter counter = new ViewCounter(8);
        for (int i = 0; i < 1000; i++) counter.increment(videoId);
        log.info(() -> "Approx views: " + counter.total(videoId));
    }
}

