// ─── File: TranscodePipeline.java ───
package com.bank.video;

import java.util.*;
import java.util.logging.*;

public class TranscodePipeline {
    private static final Logger log = Logger.getLogger("Video");
    private record Job(String videoId, String rawPath, String profile, long bitrate) {}
    private final Deque<Job> queue = new ArrayDeque<>();
    private final Map<String, List<Variant>> ladders = new HashMap<>();

    public void upload(String videoId, String rawPath) {
        // enqueue one transcoding job per quality profile (async, decoupled)
        queue.add(new Job(videoId, rawPath, "240p", 400_000));
        queue.add(new Job(videoId, rawPath, "480p", 1_000_000));
        queue.add(new Job(videoId, rawPath, "720p", 2_500_000));
        queue.add(new Job(videoId, rawPath, "1080p", 4_500_000));
        log.info(() -> "Uploaded " + videoId + ", queued 4 transcode jobs");
    }

    public void runWorkers() {
        Job j;
        while ((j = queue.poll()) != null) {
            // simulate transcoding + segmenting, produce a variant URL
            String url = "cdn://" + j.videoId() + "/" + j.profile() + "/manifest.m3u8";
            ladders.computeIfAbsent(j.videoId(), k -> new ArrayList<>())
                   .add(new Variant(j.profile(), j.bitrate(), url));
            Job fj = j;
            log.info(() -> "transcoded " + fj.videoId() + " " + fj.profile());
        }
    }
    public List<Variant> ladderOf(String videoId) {
        List<Variant> l = ladders.getOrDefault(videoId, List.of());
        l.sort(Comparator.comparingLong(Variant::bitrate));
        return l;
    }
}
