package com.bank.video;

import java.util.*;

public class AdaptiveStreamer {
    // choose the highest-bitrate variant that fits current bandwidth
    public Variant selectVariant(List<Variant> ladder, long bandwidthBps) {
        Variant chosen = ladder.get(0); // lowest as safe fallback
        for (Variant v : ladder)
            if (v.bitrate() <= bandwidthBps) chosen = v;
        return chosen;
    }
}
