// ─── File: ViewCounter.java ───
package com.bank.video;

import java.util.concurrent.atomic.AtomicLongArray;
import java.util.concurrent.ThreadLocalRandom;

// Sharded counter: spread increments across shards to avoid a single hotspot.
public class ViewCounter {
    private final int shards;
    private final java.util.Map<String, AtomicLongArray> counters = new java.util.concurrent.ConcurrentHashMap<>();

    public ViewCounter(int shards) { this.shards = shards; }

    public void increment(String videoId) {
        AtomicLongArray arr = counters.computeIfAbsent(videoId, k -> new AtomicLongArray(shards));
        int shard = ThreadLocalRandom.current().nextInt(shards); // random shard
        arr.incrementAndGet(shard);
    }
    public long total(String videoId) {
        AtomicLongArray arr = counters.get(videoId);
        if (arr == null) return 0;
        long sum = 0;
        for (int i = 0; i < shards; i++) sum += arr.get(i); // aggregate (eventually consistent)
        return sum;
    }
}
